"""KR3b tests for Minifolio (approved wording rewrites in Colour basics and Tools and prep). New behaviour only:
for each of the 29 changed fields the new text is present and the old text is gone.
Run with `python3 tests/run_all.py`, or serve the repo folder and run this file on its own."""
import os, sys
from playwright.sync_api import sync_playwright

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import test_v31 as t
from launch_helpers import wait_settled

results = []

def check(name, ok, detail=""):
    results.append(bool(ok))
    print(("PASS " if ok else "FAIL ") + name + ("" if ok else f"  -> {detail}"))

# (guide key, field, old text, new text); field is Summary or P1, P2... (paragraphs in order)
ROWS = [
    ('brighten-dark-schemes', 'P2', 'Paint the main colour a little brighter and lighter than the real reference so it reads, since small models look darker than they are. This also leaves room for washes to pull it back down. Over a black primer, give it at least two thin coats so it covers evenly.', 'Paint the main colour a little brighter and lighter than the real reference, since small models look darker than they are. This also leaves room for washes to pull it back down. Over a black primer, give it at least two thin coats so it covers evenly.'),
    ('colour-scheme-from-reference', 'P2', 'Use a colour picker on a digital copy to pull out about five main colours. Nudge them towards the pure tones rather than the in-between mixes.', 'Use a colour picker on a digital copy to pull out about five main colours. Nudge them towards the pure tones and away from the in-between mixes.'),
    ('focal-points', 'P3', 'Bend reality where it helps. Make the face lighter than the rest of the skin, nudge a reflection towards the head, and keep arms, legs or a backpack darker than the light would really leave them. Believable beats strictly correct.', 'Bend reality where it helps, as long as it still looks believable. Make the face lighter than the rest of the skin, nudge a reflection towards the head, and keep arms, legs or a backpack darker than the light would really leave them.'),
    ('muted-support-colours', 'P1', 'Lots of strong colours side by side compete, and the model looks chaotic. If everything stands out, nothing does, so decide which part should lead. Muted does not mean dark: a quiet or gritty scheme still needs punch, from deep recesses against sharp pale edges.', 'Lots of strong colours side by side compete, so nothing stands out and the model looks a mess. Decide which part should lead. Muted does not mean dark: a quiet or gritty scheme still needs punch, from deep recesses against sharp pale edges.'),
    ('cold-light-scenes', 'P2', "Moonlight needs three things: one light direction, a cold pale blue light, and low saturation in every colour. Prime with a zenithal from the moon's direction and paint the face first, then use it as the guide for where light falls elsewhere.", "For moonlight, keep to one light direction, make that light a cold pale blue, and keep every colour low in saturation. Prime with a zenithal from the moon's direction and paint the face first, then use it as the guide for where light falls elsewhere."),
    ('pushing-contrast', 'P7', 'Rather than adding many small steps near the top, a bold jump to a stark final highlight on the sharpest points often reads better. Put the brightest highlights around the face to pull the eye there.', 'A bold jump to a stark final highlight on the sharpest points often looks better than lots of small steps near the top. Put the brightest highlights around the face to pull the eye there.'),
    ('material-contrast', 'P1', "Neighbouring areas in similar colours blur into one mass at arm's length. Give touching areas clearly different colours or values, and if a model is mostly two materials, such as skin and shell, make one light and one dark. Step back to check each part still reads.", "Neighbouring areas in similar colours blur into one mass at arm's length. Give touching areas clearly different colours or values, and if a model is mostly two materials, such as skin and shell, make one light and one dark. Step back and check you can still tell the parts apart."),
    ('why-metallics-look-flat', 'P6', 'To compare metallics, paint each on the same simple shape or a strip of black card and turn it slowly under a lamp. Watch the dark reflections as well as the bright ones; that contrast is what sells metal.', 'To compare metallics, paint each on the same simple shape or a strip of black card and turn it slowly under a lamp. Watch the dark reflections as well as the bright ones; that contrast is what makes metal look like metal.'),
    ('mixing-greys-and-browns', 'P5', 'Use a little of the opposite to dull a colour that is too bright. A drop of green in a red shadow, rather than black, keeps it rich instead of dirty.', 'Use a little of the opposite to dull a colour that is too bright. A drop of green in a red shadow keeps it rich, where black would make it dirty.'),
    ('painting-grey', 'P1', 'Most models start out grey, which is why a plain grey paint job can look unfinished. The trick is to make it look chosen: give it a lean, a clear light and dark, and something colourful next to it.', 'Most models start out grey, which is why a plain grey paint job can look unfinished. To make it look chosen, give it a lean, a clear light and dark, and something colourful next to it.'),
    ('dynamic-posing', 'P3', 'Lean the whole model slightly into the movement and tilt the head to follow that line. A deliberately off-balance lean sells a charge or eagerness.', 'Lean the whole model slightly into the movement and tilt the head to follow that line. A deliberately off-balance lean suggests a charge or eagerness.'),
    ('using-colour-lab', 'P8', 'Colours on a screen are a guide, not a promise. Screens differ, and paint dries a little darker than it looks wet. Try a suggestion on a swatch card or a spare part before you commit a whole model to it.', 'Treat colours on a screen as a rough guide. Screens differ, and paint dries a little darker than it looks wet. Try a suggestion on a swatch card or a spare part before you commit a whole model to it.'),
    ('airbrush-paint-thinning', 'P7', 'Most spraying problems come down to three things: pressure, distance from the model and the paint to thinner ratio. Change one at a time and test on paper or your hand.', 'Most spraying problems come down to pressure, distance from the model or the paint to thinner ratio. Change one at a time and test on paper or your hand.'),
    ('zenithal-priming', 'P2', 'Recesses and undersides stay dark, so the model already looks lit from above. Stop once the tops are white: piling on coats leaves a chalky surface that makes later paint fuzzy. White over black still reads greyish, so brush heavy white onto the face, shoulders or other focal points for extra punch.', 'Recesses and undersides stay dark, so the model already looks lit from above. Stop once the tops are white: piling on coats leaves a chalky surface that makes later paint fuzzy. White over black still looks greyish, so brush heavy white onto the face, shoulders or other focal points to brighten them.'),
    ('sculpting-armatures', 'P7', 'Clay grips bare wire badly and thin wire can slice through it, so cover the armature in a thin skin of two-part epoxy putty, mixed until no streaks remain and wrapped fully round. You need grip, not volume.', 'Clay grips bare wire badly and thin wire can slice through it, so cover the armature in a thin skin of two-part epoxy putty, mixed until no streaks remain and wrapped fully round. It only has to grip.'),
    ('paper-and-tape-cloth', 'P8', 'The paper soaks up paint like fabric. Tape bends without cracking its paint, unlike foil that is folded after painting.', 'The paper soaks up paint like fabric. Tape bends without its paint cracking, but foil folded after painting will crack.'),
    ('scratch-building-details', 'P8', "Keep rods and strips longer than needed while working so you have something to hold, and trim at the end. Folded card boxes with glue tabs make stowage. Model a part's most recognisable shapes; a clear silhouette matters more than every detail.", "Keep rods and strips longer than needed while working so you have something to hold, and trim at the end. Folded card boxes with glue tabs make stowage. Model a part's most recognisable shapes; if the outline is clear, you do not need every detail."),
    ('sculpting-organic-texture', 'P8', 'Vary the sizes and leave some smooth areas between clusters so the texture reads clearly. Next to flesh, flat pressed facets with a few cut scratches read as hard shell.', 'Vary the sizes and leave some smooth areas between clusters so the texture stands out. Next to flesh, flat pressed facets with a few cut scratches look like hard shell.'),
    ('wire-details', 'Summary', 'Thin wire makes lightning bolts, energy arcs and tiny candles that add life to a model or scene.', 'Thin wire makes lightning bolts, energy arcs and tiny candles for a model or scene.'),
    ('building-ruined-walls', 'P4', 'Floors: use card or plastic sheet with planks or tiles scored in. Break holes with ragged edges and let joists stick out underneath. A floor that sags or hangs at an angle reads well.', 'Floors: use card or plastic sheet with planks or tiles scored in. Break holes with ragged edges and let joists stick out underneath. A floor that sags or hangs at an angle looks good too.'),
    ('scratch-built-terrain', 'P7', 'Leave room for play. Test a model on its base through doors, on steps and along walkways, keep gaps wide enough for two medium bases side by side, and floors flat. Terrain should support the models, like a stage set.', 'Leave room for play. Test a model on its base through doors, on steps and along walkways, keep gaps wide enough for two medium bases side by side, and floors flat. Think of it as a stage set for the models.'),
    ('drying-and-curing-times', 'P8', 'Every product is different, so treat these as rough starting points and check the label. Cold, damp rooms slow everything down. When in doubt, leave it overnight; that is rarely the wrong call.', 'Every product is different, so treat these as rough starting points and check the label. Cold, damp rooms slow everything down. When in doubt, leave it overnight.'),
    ('metallic-paint-handling', 'P8', 'Shade with a matching metallic, a dark wash or a thin glaze, and highlight with a lighter metallic, so the area stays reading as metal. Let metallics dry fully before handling. A satin varnish evens a patchy sheen but dulls the shine, so test it first.', 'Shade with a matching metallic, a dark wash or a thin glaze, and highlight with a lighter metallic, so the area still looks like metal. Let metallics dry fully before handling. A satin varnish evens a patchy sheen but dulls the shine, so test it first.'),
    ('paint-consistency-by-technique', 'P8', 'These are ranges, not rules. Slow, smooth display work uses more water; quick work can use paint nearly neat. Move between layering and glazing freely as the area needs.', 'Treat these as rough ranges. Slow, smooth display work uses more water; quick work can use paint nearly neat. Move between layering and glazing freely as the area needs.'),
    ('editing-model-photos', 'P4', 'Go easy on saturation. Pushing it hard destroys detail and changes your colours, so nudge it only slightly. Aim for true colour, not hiding flaws. If your lights and camera never move, save the settings as a preset.', 'Go easy on saturation. Pushing it hard destroys detail and changes your colours, so nudge it only slightly. Aim for true colour; do not edit to hide flaws. If your lights and camera never move, save the settings as a preset.'),
    ('progress-photo-records', 'P6', 'Every few months, put a new model next to an old one, on the desk and in a photo side by side. Seeing the gap is better motivation than any single compliment.', 'Every few months, put a new model next to an old one, on the desk and in a photo side by side. Seeing the gap will motivate you more than any compliment.'),
    ('plinth-backdrops', 'P4', 'Keep the backdrop quieter than the model, with fewer colours and less contrast, so it supports rather than competes.', 'Keep the backdrop quieter than the model, with fewer colours and less contrast, so it does not compete.'),
    ('using-real-objects', 'P6', 'Repaint everything, even items that already look right, so they share the painted finish of the rest of the scene. Priming it all together helps it read as one.', 'Repaint everything, even items that already look right, so they share the painted finish of the rest of the scene. Priming it all together helps it look like one piece.'),
    ('using-real-objects', 'P7', 'Measure and paint any grids, labels or small text carefully. Neat detail copied by hand is what sells the effect.', 'Measure and paint any grids, labels or small text carefully. Neat detail copied by hand is what makes it convincing.'),
]

def main():
    errors = []
    with sync_playwright() as p:
        browser = p.chromium.launch()
        page = browser.new_context(viewport={"width": 390, "height": 844}, service_workers="block").new_page()
        page.on("pageerror", lambda x: errors.append(str(x)))
        page.goto(t.URL)
        wait_settled(page)
        g = page.evaluate("() => Object.fromEntries(GUIDE_ENTRIES.map(e => [e.key, {summary: e.summary, body: e.body}]))")
        for key, fld, old, new in ROWS:
            e = g.get(key)
            val = e["summary"] if fld == "Summary" else e["body"][int(fld[1:]) - 1]
            check(f"{key} {fld}: new wording in, old gone", val == new and old not in val)
        check("no page errors", errors == [], errors)
        browser.close()
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return 0 if all(results) else 1

if __name__ == "__main__":
    sys.exit(main())
